 var old=Doc();old.Version=version;old.Annotations.Add(new(){Kind=AnnotationKind.Callout,Text="Giữ chữ",X1=20,Y1=30,X2=200,Y2=160,FillEnabled=false,FillColor="#123456",StrokeEnabled=false});old.Validate(1200,800,"hash");var a=old.Annotations[0];Check(old.Version==8&&a.FillEnabled&&a.FillColor=="#FFFFFF"&&a.StrokeEnabled&&TextStudio.Padding(a)==12,"Old callout retains its formerly implicit white body: schema "+version);
}
Check(TextStudio.Padding(new(){Kind=AnnotationKind.Text})==0&&TextStudio.Padding(new(){Kind=AnnotationKind.Callout})==12,"Legacy text and callout padding defaults are separate");
