var fillDoc=Doc();var rectangle=new Annotation{Kind=AnnotationKind.Rectangle,X1=100,Y1=100,X2=200,Y2=180,FillEnabled=true,FillColor="#123456"};fillDoc.Annotations.Add(rectangle);var session=new EditorSession(fillDoc);session.Change(d=>d.Annotations[0].FillEnabled=false);Check(!rectangle.FillEnabled&&rectangle.FillColor=="#123456","No fill clears only enabled state and retains chosen color");session.Undo();Check(session.Document.Annotations[0].FillEnabled,"Undo no fill restores background");session.Redo();Check(!session.Document.Annotations[0].FillEnabled,"Redo no fill remains transparent");
var network=Doc();var first=new Annotation{Kind=AnnotationKind.Rectangle,X1=10,Y1=20,X2=100,Y2=90};var second=new Annotation{Kind=AnnotationKind.Ellipse,X1=300,Y1=200,X2=400,Y2=300};var connector=new Annotation{Kind=AnnotationKind.Arrow,Route=ConnectorRoute.Curve,StartAnchor=new(first.Id,1,.5),EndAnchor=new(second.Id,0,.5),Control=new(200,10)};network.Annotations.AddRange([first,second,connector,text.Copy()]);AnnotationEditing.Group(network,[first.Id,second.Id,connector.Id]);ConnectorStudio.Resolve(network);
