var target=Doc();var pasted=AnnotationClipboard.Paste(target,json,16,Box);Check(pasted.Count==3&&target.Annotations.All(a=>a.Id!=first.Id&&a.Id!=second.Id&&a.Id!=connector.Id),"Paste allocates fresh object IDs");var linked=target.Annotations.Single(a=>a.Kind==AnnotationKind.Arrow);Check(pasted.Contains(linked.StartAnchor!.TargetId)&&pasted.Contains(linked.EndAnchor!.TargetId),"Pasted connector points to pasted targets");Check(target.Annotations.Where(a=>a.GroupId!=null).Select(a=>a.GroupId).Distinct().Count()==1&&target.Annotations[0].GroupId!=first.GroupId,"Paste creates independent group identity");target.Validate(1200,800,"hash");
var repeated=AnnotationClipboard.Paste(target,json,32,Box);Check(!repeated.Overlaps(pasted)&&target.Annotations.Count==6,"Repeated paste remains independent");var pastedArrow=target.Annotations.Single(a=>repeated.Contains(a.Id)&&a.Kind==AnnotationKind.Arrow);Check(repeated.Contains(pastedArrow.StartAnchor!.TargetId),"Repeated network paste does not link back to prior paste");
