var textJson=AnnotationClipboard.Copy(doc,[text.Id]);var small=new EditorDocument{OriginalWidth=100,OriginalHeight=60};AnnotationClipboard.Paste(small,textJson,16,Box);var smallText=small.Annotations[0];Check(smallText.FontSize==text.FontSize&&smallText.TextWidth==300&&smallText.FontFamily=="Arial","Cross-image paste keeps typography dimensions without resize");
var locked=text.Copy();locked.Locked=true;locked.Visible=false;var lockedDoc=Doc();lockedDoc.Annotations.Add(locked);var copyHidden=AnnotationClipboard.Copy(lockedDoc,[locked.Id]);var editable=Doc();AnnotationClipboard.Paste(editable,copyHidden,16,Box);Check(editable.Annotations[0].Visible&&!editable.Annotations[0].Locked,"Pasted copies are visible and editable while original state stays unchanged");
var history=new EditorSession(Doc());history.Change(d=>AnnotationClipboard.Paste(d,json,16,Box));Check(history.Document.Annotations.Count==3&&history.CanUndo,"Paste is one history transaction");history.Undo();Check(history.Document.Annotations.Count==0,"Undo paste removes entire network");history.Redo();Check(history.Document.Annotations.Count==3&&history.Document.Annotations[^1].StartAnchor!=null,"Redo paste restores complete linked network");
